func (q *Queries) UpdateEventLatest(ctx context.Context, arg UpdateEventLatestParams) error {
	_, err := q.db.Exec(ctx, updateEventLatest,
		arg.ID,
		arg.LastMinPriceCents,
		arg.LastMaxPriceCents,
		arg.LastAvailability,
		arg.NextPollAt,
	)
	return err
}

